package in.tutorlink.service; import in.tutorlink.entity.*; import in.tutorlink.repository.*; import org.springframework.stereotype.*; import java.util.*;
@Service public class MatchingService { final TutorProfileRepository tutors; public MatchingService(TutorProfileRepository t){tutors=t;} public record Match(TutorProfile tutor,int score){}
 public List<Match> tutorsFor(TuitionRequirement r){return tutors.findAll().stream().map(t->{int s=0;if(!Collections.disjoint(lower(t.subjects),lower(r.subjects)))s+=30;if(t.classes.contains(r.studentClass))s+=20;if(eq(t.location,r.location))s+=20;if(eq(t.teachingMode,r.teachingMode)||"BOTH".equalsIgnoreCase(t.teachingMode)||"BOTH".equalsIgnoreCase(r.teachingMode))s+=15;if(t.monthlyFee<=r.budget)s+=10;if(t.experienceYears>0)s+=5;return new Match(t,s);}).filter(m->m.score>0).sorted(Comparator.comparingInt(Match::score).reversed()).toList();} private boolean eq(String a,String b){return a!=null&&b!=null&&a.equalsIgnoreCase(b);} private Set<String> lower(Set<String>s){return s.stream().map(String::toLowerCase).collect(java.util.stream.Collectors.toSet());}}
